import json, subprocess, sys

DIR = {
  "sip:ember@studio.test": ["sip:e1@alias.studio.test", "tel:+12025550121"],
  "sip:desk@sales.test": ["tel:+12025550122"],
}
ACC = {"session-k": {"primary":"sip:ember@studio.test","allow":["sip:desk@sales.test"]}}
GW = {
  "edge": {"local_domains":["studio.test","sales.test"],"peers":{}},
  "inside": {"local_domains":[],"peers":{"edge":["studio.test","sales.test"]}},
}
LOC={"kind":"local","subject":"session-k"}
PEER={"kind":"peer","name":"edge"}

def mk(fromhdr="<sip:ember@studio.test>;tag=q7", to="<sip:inbox@relay.test>;tag=to9", extra="", body="hi",
       cseq="0009 MESSAGE", clen=None):
    if clen is None: clen=len(body)
    return ("MESSAGE sip:INBOX@Relay.TEST. SIP/2.0\r\n"
            f"From: {fromhdr}\r\n"
            f"To: {to}\r\n"
            "Call-ID: sample-73\r\n"
            f"CSeq: {cseq}\r\n" + extra + f"Content-Type: text/plain; charset=utf-8\r\nContent-Length: {clen}\r\n\r\n{body}")

jobs=[
 {"gateway":"edge","ingress":LOC,"trusted_out":True,"raw":mk()},
 {"gateway":"edge","ingress":LOC,"trusted_out":False,"raw":mk()},
 {"gateway":"edge","ingress":LOC,"trusted_out":True,"raw":mk(fromhdr="<sip:anonymous@anonymous.invalid>")},
 {"gateway":"edge","ingress":LOC,"trusted_out":False,"raw":mk(fromhdr="<sip:anonymous@anonymous.invalid>")},
 {"gateway":"inside","ingress":PEER,"trusted_out":True,"source":0},
 {"gateway":"inside","ingress":PEER,"trusted_out":True,"source":2},
 {"gateway":"inside","ingress":PEER,"trusted_out":True,"source":1},
 {"gateway":"edge","ingress":LOC,"trusted_out":True,"source":4},
 {"gateway":"edge","ingress":LOC,"trusted_out":True,"source":3},
 {"gateway":"edge","ingress":LOC,"trusted_out":True,"source":5},
]
batch={"directory":DIR,"accounts":ACC,"gateways":GW,"jobs":jobs}
out=subprocess.run([sys.executable,"/workspace/submission/gateway.py"],input=json.dumps(batch).encode(),capture_output=True)
if out.returncode!=0:
    print("EXIT",out.returncode,out.stderr.decode()[:3000]); sys.exit(1)
res=json.loads(out.stdout)["results"]
for i,r in enumerate(res):
    print("=== job",i, r.get("status"), r.get("reason",""), r.get("identity",""), "private=",r.get("private"))
    if "wire" in r:
        print(repr(r["wire"]))
        print(r["wire"])
PYEOF
python3 tmp/t3.py
